package handler
import("net/http";"net/http/httptest";"strings";"testing";"time";"github.com/golang-jwt/jwt/v5";"github.com/multica-ai/multica/server/internal/auth")
func TestTaskFlowOwnerNativeSessionPrivateReview(t *testing.T){
 owner:="fixture-owner";email:="owner@example.test";origin:="https://tf.example.test"
 claims:=func()jwt.MapClaims{return jwt.MapClaims{"sub":owner,"email":email,"sid":strings.Repeat("a",32),"iat":time.Now().Add(-time.Minute).Unix(),"exp":time.Now().Add(time.Hour).Unix()}}
 request:=func(c jwt.MapClaims)*http.Request{token,e:=jwt.NewWithClaims(jwt.SigningMethodHS256,c).SignedString(auth.JWTSecret());if e!=nil{t.Fatal(e)};r:=httptest.NewRequest("POST","https://tf.example.test/api/taskflow-drive/setup",strings.NewReader("{}"));r.Header.Set("Authorization","Bearer "+token);for k,v:=range map[string]string{"Origin":origin,"Sec-Fetch-Site":"same-origin","Sec-Fetch-Mode":"cors","Sec-Fetch-Dest":"empty","Content-Type":"application/json","X-TaskFlow-Drive-Setup":"1"}{r.Header.Set(k,v)};return r}
 t.Run("native_exact_owner",func(t *testing.T){r:=request(claims());if !taskflowDriveOwnerNativeSession(r,owner,owner,email,origin){t.Fatal("valid native refused")}})
 for _,header:=range []string{"Origin","Sec-Fetch-Site","Sec-Fetch-Mode","Sec-Fetch-Dest","Content-Type","X-TaskFlow-Drive-Setup"}{t.Run("missing_"+header,func(t *testing.T){r:=request(claims());r.Header.Del(header);if taskflowDriveOwnerNativeSession(r,owner,owner,email,origin){t.Fatal("missing header allowed")}})}
 for _,h:=range []string{"Origin","Sec-Fetch-Site","Sec-Fetch-Mode","Sec-Fetch-Dest","Content-Type","X-Actor-Source","X-Agent-ID","X-Task-ID"}{t.Run("wrong_"+h,func(t *testing.T){r:=request(claims());r.Header.Set(h,"foreign");if taskflowDriveOwnerNativeSession(r,owner,owner,email,origin){t.Fatal("wrong header allowed")}})}
 for _,prefix:=range []string{"sat_","mat_","mul_","mcn_","cli_"}{t.Run(prefix,func(t *testing.T){r:=request(claims());r.Header.Set("Authorization","Bearer "+prefix+"fixture");if taskflowDriveOwnerNativeSession(r,owner,owner,email,origin){t.Fatal("machine credential allowed")}})}
 for _,key:=range []string{"sub","email","sid","iat","exp"}{t.Run("missing_claim_"+key,func(t *testing.T){c:=claims();delete(c,key);if taskflowDriveOwnerNativeSession(request(c),owner,owner,email,origin){t.Fatal("missing claim allowed")}})}
 for key,value:=range map[string]any{"sub":"other-owner","email":"other@example.test","sid":"not-session","exp":time.Now().Add(-time.Minute).Unix(),"iat":time.Now().Add(time.Hour).Unix(),"aud":"other","iss":"other","scope":"agent","agent_id":"agent","task_id":"task"}{t.Run("wrong_claim_"+key,func(t *testing.T){c:=claims();c[key]=value;if taskflowDriveOwnerNativeSession(request(c),owner,owner,email,origin){t.Fatal("wrong claim allowed")}})}
 t.Run("signed_other_key",func(t *testing.T){r:=request(claims());token,_:=jwt.NewWithClaims(jwt.SigningMethodHS256,claims()).SignedString([]byte("fixture-other-key"));r.Header.Set("Authorization","Bearer "+token);if taskflowDriveOwnerNativeSession(r,owner,owner,email,origin){t.Fatal("foreign signature allowed")}})
 t.Run("signed_wrong_algorithm",func(t *testing.T){r:=request(claims());token,_:=jwt.NewWithClaims(jwt.SigningMethodHS512,claims()).SignedString(auth.JWTSecret());r.Header.Set("Authorization","Bearer "+token);if taskflowDriveOwnerNativeSession(r,owner,owner,email,origin){t.Fatal("wrong algorithm allowed")}})
 t.Run("query_token",func(t *testing.T){r:=request(claims());r.URL.RawQuery="token=fixture";if taskflowDriveOwnerNativeSession(r,owner,owner,email,origin){t.Fatal("query accepted")}})
 t.Run("identity_mismatch",func(t *testing.T){r:=request(claims());if taskflowDriveOwnerNativeSession(r,"other",owner,email,origin){t.Fatal("middleware mismatch accepted")}})
}
